/*
 * ProbeEncoding.java -- dumps the JDK GBK charset mapping (M3-02).
 *
 * WHY this probe: the product reads file datasets with
 * `new FileObject(fileName, cs, "s", ctx)` where cs comes from
 * FileDataSetConfig.getEncoding() and defaults to "GBK"
 * (FileDataSetConfig.java:25, FileDataSetFactory.java:93/112/414). So the
 * product's GBK decoding behaviour IS the JDK's GBK charset behaviour.
 * Rather than trusting a third-party mapping table, this probe dumps the
 * JDK's own mapping over the whole GBK definition domain:
 *
 *   lead  0x81..0xFE
 *   trail 0x40..0xFE except 0x7F
 *
 * and writes every defined two-byte sequence as (u16 BE gbk, u16 BE unicode)
 * pairs into gbk_jdk.bin. That file is the single source of truth for
 * crates/rpx-engine/data/gbk.bin (generated by scripts/gen_gbk_table.py,
 * which only sorts + adds a header -- it never invents a mapping).
 *
 * Two behaviours are pinned by this dump, both matching the JDK decoder's
 * default REPLACE action:
 *   - a sequence that decodes to U+FFFD is NOT defined (excluded);
 *   - single bytes >= 0x80 outside a valid pair are malformed (the Rust
 *     side reports an explicit error instead of replacing -- see
 *     crates/rpx-engine/src/encoding.rs module docs).
 */
package rpx.fixtures;

import java.io.DataOutputStream;
import java.io.FileOutputStream;

public class ProbeEncoding {
	public static void main(String[] args) throws Exception {
		DataOutputStream out = new DataOutputStream(new FileOutputStream("gbk_jdk.bin"));
		int count = 0;
		for (int lead = 0x81; lead <= 0xFE; lead++) {
			for (int trail = 0x40; trail <= 0xFE; trail++) {
				if (trail == 0x7F) {
					continue;
				}
				byte[] bs = new byte[] { (byte) lead, (byte) trail };
				String s = new String(bs, "GBK");
				if (s.length() == 1 && s.charAt(0) != '\uFFFD') {
					out.writeShort(lead << 8 | trail);
					out.writeShort(s.charAt(0));
					count++;
				}
			}
		}
		out.close();
		System.out.println("GBK_DUMP_PAIRS=" + count);

		// Sanity anchors (well-known GBK codepoints; the codepoints are the
		// assertion -- the JDK value is the ground truth, not our memory).
		String[] anchors = {
			new String(new byte[] { (byte) 0xD6, (byte) 0xD0 }, "GBK"), // U+4E2D
			new String(new byte[] { (byte) 0xC7, (byte) 0xEF }, "GBK"), // U+79CB
			new String(new byte[] { (byte) 0xC1, (byte) 0xAC }, "GBK"), // U+8FDE
			new String(new byte[] { (byte) 0xB2, (byte) 0xCB }, "GBK"), // U+83DC
			new String(new byte[] { (byte) 0xB4, (byte) 0xF3 }, "GBK"), // U+5927
			new String(new byte[] { (byte) 0xA1, (byte) 0xA1 }, "GBK"), // U+3000
		};
		StringBuilder sb = new StringBuilder("GBK_ANCHORS=");
		for (int i = 0; i < anchors.length; i++) {
			if (i > 0) {
				sb.append('|');
			}
			sb.append(anchors[i]).append('/').append((int) anchors[i].charAt(0));
		}
		System.out.println(sb);
	}
}
